"""Español — profetas (prophets_001 … prophets_150)."""

T = {
"prophets_001": ("¿Qué profeta construyó el arca por orden de Allah?", ["Nuh (Noé)", "Ibrahim (Abraham)", "Musa (Moisés)", "Yusuf (José)"], "Allah ordenó a Nuh construir el arca para salvar a los creyentes del diluvio."),
"prophets_002": ("¿Qué profeta fue arrojado a un fuego que Allah hizo frío y seguro para él?", ["Ibrahim (Abraham)", "Nuh (Noé)", "Dawud (David)", "Ayyub (Job)"], "Allah ordenó al fuego ser frío y seguro para Ibrahim."),
"prophets_003": ("¿Qué profeta fue tragado por un enorme pez?", ["Yunus (Jonás)", "Ilyas (Elías)", "Idris (Enoc)", "Zakariyya (Zacarías)"], "Yunus fue tragado por el pez tras dejar a su pueblo enojado; Allah lo perdonó."),
"prophets_004": ("¿Qué profeta interpretó el sueño del rey de las siete vacas gordas y las siete flacas?", ["Yusuf (José)", "Ya'qub (Jacob)", "Isma'il (Ismael)", "Ishaq (Isaac)"], "Yusuf interpretó el sueño del rey: siete años de abundancia seguidos de siete de hambruna."),
"prophets_005": ("Según el Corán, ¿a qué profeta le habló Allah directamente?", ["Musa (Moisés)", "Harun (Aarón)", "Yusuf (José)", "Sulaiman (Salomón)"], "El Corán afirma que Allah habló a Musa directamente."),
"prophets_006": ("¿Qué profeta podía entender el lenguaje de los pájaros?", ["Sulaiman (Salomón)", "Dawud (David)", "Yunus (Jonás)", "Yusuf (José)"], "Allah enseñó a Sulaiman el lenguaje de los pájaros."),
"prophets_007": ("¿A qué profeta se le dio la escritura llamada Zabur (Salmos)?", ["Dawud (David)", "Musa (Moisés)", "Isa (Jesús)", "Ibrahim (Abraham)"], "El Corán menciona que el Zabur fue dado a Dawud."),
"prophets_008": ("¿Qué profeta nació sin padre, por la palabra de Allah «Sé, y es»?", ["Isa (Jesús)", "Yahya (Juan)", "Isma'il (Ismael)", "Ishaq (Isaac)"], "El Corán describe el nacimiento milagroso de Isa sin padre, solo por la palabra de Allah."),
"prophets_009": ("¿Qué capítulo (sura) del Corán lleva el nombre de la madre de un profeta?", ["Maryam", "Yusuf", "Nuh", "Hud"], "La sura 19, Maryam, lleva el nombre de la madre del profeta Isa."),
"prophets_010": ("¿Qué profeta fue probado con una grave enfermedad y es alabado por su paciencia?", ["Ayyub (Job)", "Zakariyya (Zacarías)", "Yahya (Juan)", "Idris (Enoc)"], "Ayyub se mantuvo paciente en una prueba muy dura, y Allah lo recompensó."),
"prophets_011": ("¿Ante quién ordenó Allah a los ángeles postrarse, como señal de honor?", ["Adam", "Nuh (Noé)", "Ibrahim (Abraham)", "Musa (Moisés)"], "Allah ordenó a los ángeles postrarse ante Adam como muestra de honor, no de adoración."),
"prophets_012": ("¿Qué profeta es llamado «Jalilullah», el amigo íntimo de Allah?", ["Ibrahim (Abraham)", "Musa (Moisés)", "Isa (Jesús)", "Muhammad ﷺ"], "El Corán describe a Ibrahim como el amigo íntimo (jalil) de Allah."),
"prophets_013": ("¿Qué profeta fue arrojado a un pozo por sus hermanos?", ["Yusuf (José)", "Bunyamin (Benjamín)", "Ya'qub (Jacob)", "Isma'il (Ismael)"], "Los hermanos de Yusuf lo arrojaron a un pozo por celos."),
"prophets_014": ("¿El pueblo de qué profeta fue destruido por un diluvio tras rechazarlo?", ["Nuh (Noé)", "Hud", "Salih", "Shu'ayb"], "El pueblo de Nuh fue sumergido por el diluvio tras rechazar obstinadamente su mensaje."),
"prophets_015": ("¿Qué profeta vio el mar abrirse para salvar a su pueblo del Faraón?", ["Musa (Moisés)", "Harun (Aarón)", "Yusuf (José)", "Isma'il (Ismael)"], "Allah ordenó a Musa golpear el mar, que se abrió para que pasaran los creyentes."),
"prophets_016": ("¿Qué profeta, junto a su padre Dawud, juzgó el caso de un campo pastado por ovejas?", ["Sulaiman (Salomón)", "Isma'il (Ismael)", "Yusuf (José)", "Ishaq (Isaac)"], "El Corán relata que Sulaiman y Dawud juzgaron este caso, y Allah dio a Sulaiman su comprensión."),
"prophets_017": ("¿A la madre de quién se le indicó poner a su bebé en un río?", ["Musa (Moisés)", "Isa (Jesús)", "Yusuf (José)", "Isma'il (Ismael)"], "Allah inspiró a la madre de Musa a ponerlo en un cofre sobre el río para protegerlo."),
"prophets_018": ("¿La camella de quién fue una señal dada a su pueblo, los Zamud?", ["Salih", "Hud", "Shu'ayb", "Lut (Lot)"], "Allah envió una camella como señal al pueblo de Zamud a través del profeta Salih."),
"prophets_019": ("¿A qué profeta enseñó Allah los nombres de todas las cosas?", ["Adam", "Nuh (Noé)", "Ibrahim (Abraham)", "Musa (Moisés)"], "Allah enseñó a Adam los nombres de todas las cosas, y los ángeles reconocieron la sabiduría de Allah."),
"prophets_020": ("¿Qué profeta habló a la gente siendo aún un bebé en la cuna?", ["Isa (Jesús)", "Yahya (Juan)", "Yusuf (José)", "Ismail (Ismael)"], "El bebé Isa habló desde la cuna: «Soy el siervo de Allah; Él me ha dado la Escritura»."),
"prophets_021": ("¿Con qué hijo levantó Ibrahim los cimientos de la Ka'ba?", ["Ismail (Ismael)", "Ishaq (Isaac)", "Yaqub (Jacob)", "Yusuf (José)"], "«Y cuando Ibrahim e Ismail levantaban los cimientos de la Casa…»: construyeron juntos."),
"prophets_022": ("¿Qué hijo fue anunciado al profeta Zakariyya en su vejez?", ["Yahya (Juan)", "Isa (Jesús)", "Ismail (Ismael)", "Ishaq (Isaac)"], "«Oh Zakariyya, te anunciamos un niño cuyo nombre será Yahya.»"),
"prophets_023": ("¿En qué se convirtió el bastón de Musa cuando Allah le dijo que lo arrojara?", ["En una serpiente que se movía", "En un pájaro", "En un manantial", "En una luz"], "«¡Arrójalo, oh Musa!» Lo arrojó, y se convirtió en una serpiente que se movía veloz."),
"prophets_024": ("En su sueño, ¿qué vio el joven Yusuf postrarse ante él?", ["Once estrellas, el sol y la luna", "Siete vacas gordas", "Una lluvia de oro", "Un jardín de palmeras"], "Yusuf vio once estrellas, el sol y la luna postrándose ante él: una señal de su destino."),
"prophets_025": ("¿A qué pueblo fue enviado el profeta Hud?", ["A los 'Ad", "A los Zamud", "Al pueblo de Madyan", "Al pueblo del Faraón"], "«Y a los 'Ad, su hermano Hud…»: los llamó a adorar solo a Allah."),
"prophets_026": ("¿A qué pueblo fue enviado el profeta Shu'ayb?", ["Al pueblo de Madyan", "A los 'Ad", "A los Zamud", "Al pueblo de Nuh"], "«Y a Madyan, su hermano Shu'ayb…»: les ordenó dar medida y peso justos."),
"prophets_027": ("¿Qué profeta es llamado «Dhun-Nun» (el del pez) en el Corán?", ["Yunus (Jonás)", "Musa (Moisés)", "Sulayman (Salomón)", "Ayyub (Job)"], "«Y Dhun-Nun, cuando se fue enojado…»: es Yunus, luego tragado por el pez."),
"prophets_028": ("¿En qué sura viaja Musa para aprender de un siervo al que Allah dio un conocimiento especial?", ["Al-Kahf (La Caverna)", "Yusuf", "Maryam", "An-Naml"], "En la sura Al-Kahf, Musa acompaña a un siervo sabio y aprende paciencia ante lo que aún no comprende."),
"prophets_029": ("¿Qué profeta es mencionado por su nombre más veces en el Corán?", ["Musa (Moisés)", "Ibrahim (Abraham)", "Nuh (Noé)", "Isa (Jesús)"], "Musa es el profeta más nombrado en el Corán; su historia con el Faraón vuelve muchas veces."),
"prophets_030": ("¿Cuántos profetas son mencionados por su nombre en el Corán?", ["25", "10", "50", "99"], "Veinticinco profetas son nombrados en el Corán, de Adam a Muhammad ﷺ."),
"prophets_031": ("Con el permiso de Allah, ¿qué profeta curó al ciego y al leproso?", ["Isa (Jesús)", "Musa (Moisés)", "Dawud (David)", "Yunus (Jonás)"], "Isa curó al ciego y al leproso con el permiso de Allah: una señal para su pueblo."),
"prophets_032": ("Según el Corán, ¿cuánto tiempo permaneció Nuh entre su pueblo llamándolo a Allah?", ["950 años", "100 años", "300 años", "40 años"], "«Permaneció entre ellos mil años menos cincuenta»: 950 años de paciente llamada."),
"prophets_033": ("Según el Corán, ¿de qué creó Allah a Adam?", ["De arcilla", "De luz", "De fuego", "De agua"], "Allah dijo a los ángeles: «Voy a crear un ser humano de arcilla»."),
"prophets_034": ("¿Quién tentó a Adam y a su esposa a comer del árbol prohibido?", ["Shaytan (Iblis)", "Un ángel", "Un pájaro", "Un rey"], "Shaytan les susurró para que comieran del árbol que Allah había prohibido."),
"prophets_035": ("¿Qué razón dio Iblis para negarse a postrarse ante Adam?", ["«Soy mejor que él: me creaste de fuego y a él de arcilla»", "No sabía quién era Adam", "Tenía miedo de los ángeles", "Estaba dormido"], "Iblis se negó por orgullo: «Me creaste de fuego, y a él lo creaste de arcilla»."),
"prophets_036": ("Tras la muerte entre los dos hijos de Adam, ¿qué animal envió Allah para mostrar cómo enterrar el cuerpo?", ["Un cuervo", "Un perro", "Una paloma", "Un zorro"], "Allah envió un cuervo que escarbó la tierra para mostrar al asesino cómo ocultar el cuerpo de su hermano."),
"prophets_037": ("¿Qué dice el Corán sobre el profeta Idris?", ["Allah lo elevó a un lugar muy alto", "Construyó un arca", "Fue tragado por un pez", "Habló con las hormigas"], "«Y lo elevamos a un lugar muy alto.»"),
"prophets_038": ("¿Qué hizo el hijo de Nuh cuando su padre lo llamó al arca?", ["Se negó y dijo que se refugiaría en una montaña", "Subió el primero", "Construyó su propia arca", "Fue a reunir animales"], "Dijo: «Me refugiaré en una montaña»; las olas lo cubrieron."),
"prophets_039": ("¿Sobre qué monte se posó el arca de Nuh, según el Corán?", ["El monte Yudi", "El monte Sinaí", "El monte Uhud", "El monte Arafat"], "«Y el arca se posó sobre el Yudi.»"),
"prophets_040": ("¿Qué ordenó Allah a Nuh cargar en el arca?", ["Una pareja de cada especie, y los creyentes", "Solo a su familia", "Solo pájaros", "Oro y plata"], "«Carga en ella una pareja de cada especie, y a tu familia… y a quien haya creído.»"),
"prophets_041": ("¿Qué hicieron los jefes del pueblo de Nuh al verlo construir el arca?", ["Se burlaron de él", "Lo ayudaron", "Le trajeron madera", "Rezaron con él"], "Cada vez que pasaban jefes de su pueblo, se burlaban de él."),
"prophets_042": ("¿Cómo describe el Corán a Nuh en la sura Al-Isra?", ["Un siervo agradecido", "Un rey poderoso", "Un gran viajero", "Un hombre silencioso"], "«Ciertamente, era un siervo agradecido.»"),
"prophets_043": ("¿Cómo fue destruido el pueblo de 'Ad, al que fue enviado Hud?", ["Por un viento violento y furioso", "Por un diluvio", "Por una lluvia de piedras", "Por un terremoto"], "«En cuanto a los 'Ad, fueron destruidos por un viento glacial y violento.»"),
"prophets_044": ("¿Qué alcanzó a los Zamud, el pueblo de Salih?", ["Un grito terrible", "Un diluvio", "Una hambruna", "Una plaga de langostas"], "«Y el grito alcanzó a los que habían sido injustos.»"),
"prophets_045": ("¿Cómo se llama el padre de Ibrahim mencionado en el Corán?", ["Azar", "Tarih", "Lut", "Kan'an"], "«Ibrahim dijo a su padre Azar: ¿tomas ídolos por dioses?»"),
"prophets_046": ("Tras romper los ídolos, ¿cuál dejó intacto Ibrahim?", ["El más grande", "El más pequeño", "El de oro", "Ninguno, los rompió todos"], "Los hizo pedazos, salvo el mayor, para que su pueblo lo interrogara."),
"prophets_047": ("Tras ver ponerse la estrella, la luna y luego el sol, ¿qué declaró Ibrahim?", ["«No amo a los que se ponen»", "«El sol es mi señor»", "«La luna es la más bella»", "«Voy a dormir»"], "Cuando cada uno se ponía, decía: «No amo a los que se ponen», y se volvió hacia el Creador."),
"prophets_048": ("¿Cuántas aves dijo Allah a Ibrahim que tomara, para mostrarle cómo da vida a los muertos?", ["Cuatro", "Dos", "Siete", "Doce"], "«Toma cuatro aves… luego llámalas: vendrán a ti a toda prisa.»"),
"prophets_049": ("¿Qué sirvió Ibrahim a sus huéspedes, los ángeles que traían la buena noticia?", ["Un ternero asado", "Dátiles", "Leche", "Pan y miel"], "«No tardó en traer un ternero asado.»"),
"prophets_050": ("¿Qué buena noticia trajeron los ángeles a la esposa de Ibrahim?", ["El nacimiento de Ishaq", "Un viaje", "Una gran riqueza", "Lluvia abundante"], "«Le anunciamos a Ishaq, y después de Ishaq, a Ya'qub.»"),
"prophets_051": ("¿Cómo reaccionó el hijo de Ibrahim cuando su padre le contó el sueño de sacrificarlo?", ["Aceptó: «Haz lo que se te ordena»", "Huyó", "Lloró y se negó", "Se escondió"], "Dijo: «Padre mío, haz lo que se te ordena». Y Allah lo rescató con un gran sacrificio."),
"prophets_052": ("En su oración, ¿dónde dice Ibrahim que estableció a parte de su familia?", ["En un valle sin cultivo, junto a la Casa Sagrada", "Junto al Nilo", "En un bosque", "En una isla"], "«He establecido a parte de mi descendencia en un valle sin cultivo, junto a Tu Casa Sagrada.»"),
"prophets_053": ("¿Qué pidió Ibrahim para la ciudad de La Meca en su oración?", ["Que fuera una ciudad segura y su gente recibiera frutos", "Que fuera un reino", "Que siempre lloviera allí", "Que tuviera un río"], "«Señor mío, haz de esta una ciudad segura y provee a su gente de frutos.»"),
"prophets_054": ("Al levantar la Ka'ba, Ibrahim e Isma'il pidieron a Allah enviar entre sus descendientes…", ["Un mensajero de entre ellos, que recitara Sus versículos", "Un rey", "Un ejército", "Un tesoro"], "«Señor nuestro, envía entre ellos un mensajero de ellos mismos que les recite Tus versículos.»"),
"prophets_055": ("El Corán dice que un profeta fue, por sí solo, «una nación (umma)». ¿Cuál?", ["Ibrahim", "Nuh", "Musa", "Sulayman"], "«Ciertamente, Ibrahim era una nación, devoto obediente a Allah, recto.»"),
"prophets_056": ("¿Por qué cualidad alaba el Corán a Isma'il en la sura Maryam?", ["Era fiel a su promesa", "Era muy rico", "Era un rey", "Sabía nadar"], "«Ciertamente, era fiel a su promesa, y era mensajero y profeta.»"),
"prophets_057": ("¿Qué castigo cayó sobre el pueblo de Lut?", ["Una lluvia de piedras de arcilla cocida", "Un diluvio", "Una plaga de insectos", "Una sequía"], "«Volcamos la ciudad y llovimos sobre ella piedras de arcilla cocida.»"),
"prophets_058": ("¿A las esposas de qué dos profetas pone el Corán como ejemplo de incredulidad?", ["Nuh y Lut", "Ibrahim y Musa", "Dawud y Sulayman", "Ayyub y Yunus"], "«Allah pone como ejemplo de los incrédulos a la esposa de Nuh y a la esposa de Lut.»"),
"prophets_059": ("¿Quién era el padre de Ya'qub?", ["Ishaq", "Isma'il", "Ibrahim", "Yusuf"], "Los ángeles anunciaron a la esposa de Ibrahim «Ishaq, y después de Ishaq, Ya'qub»."),
"prophets_060": ("¿Qué le ocurrió a la vista de Ya'qub de tanto llorar por Yusuf?", ["Sus ojos se volvieron blancos", "Veía mejor de noche", "Nada cambió", "Perdió un ojo"], "«Sus ojos se volvieron blancos de tristeza, y la contenía.»"),
"prophets_061": ("¿Qué devolvió la vista a Ya'qub?", ["La camisa de Yusuf echada sobre su rostro", "Una planta", "Agua de Zamzam", "Un ungüento"], "Yusuf dijo: «Echad mi camisa sobre el rostro de mi padre; recobrará la vista»."),
"prophets_062": ("¿Qué prefirió Yusuf antes que ceder a lo que le proponían indebidamente?", ["La prisión", "El exilio", "La riqueza", "El silencio"], "«Señor mío, la prisión me es más querida que aquello a lo que me invitan.»"),
"prophets_063": ("En prisión, dos jóvenes contaron a Yusuf sus sueños. ¿Qué vio uno de ellos?", ["Que prensaba uvas", "Que volaba", "Que pastoreaba ovejas", "Que cavaba un pozo"], "Uno se vio prensando vino; el otro, llevando pan sobre la cabeza del que comían los pájaros."),
"prophets_064": ("¿Cuántos años de abundancia y luego de sequía predijo Yusuf al rey?", ["Siete y siete", "Tres y tres", "Diez y diez", "Uno y uno"], "«Sembraréis siete años… luego vendrán siete años difíciles.»"),
"prophets_065": ("¿Qué cargo pidió Yusuf al rey de Egipto?", ["Los graneros del país", "El mando del ejército", "El trono", "El tesoro de oro"], "«Ponme al frente de los graneros del país: soy un guardián sabio.»"),
"prophets_066": ("¿Qué hizo poner Yusuf en el equipaje de su hermano menor para retenerlo a su lado?", ["La copa del rey", "Una bolsa de oro", "Una carta", "Su camisa"], "«Puso la copa en el saco de su hermano.»"),
"prophets_067": ("¿Qué consejo dio Ya'qub a sus hijos antes de entrar en Egipto?", ["Entrar por puertas distintas", "Viajar de noche", "Disfrazarse", "Llevar regalos"], "«No entréis por una sola puerta, sino por puertas distintas.»"),
"prophets_068": ("¿Por qué fueron los hermanos de Yusuf a Egipto cuando él gobernaba allí?", ["Para obtener provisiones durante la hambruna", "Para encontrarlo", "Para peregrinar", "Para vender camellos"], "Sus hermanos vinieron por grano; entraron ante él y no lo reconocieron."),
"prophets_069": ("¿En qué casa fue acogido el bebé Musa tras ser puesto en el río?", ["En la del Faraón", "En la de un pastor", "En la de un pescador", "En la de un mercader"], "La familia del Faraón lo recogió, para que un día fuera para ellos enemigo y motivo de pesar."),
"prophets_070": ("¿Cómo volvió finalmente el bebé Musa con su madre?", ["Rechazó a todas las nodrizas y su hermana propuso a su madre", "El Faraón lo devolvió por compasión", "Su madre lo robó de noche", "Un ángel lo llevó"], "Allah hizo que rechazara a las nodrizas; su hermana propuso una casa: era la de su madre, que lo amamantó."),
"prophets_071": ("¿Por qué tuvo Musa que abandonar Egipto a toda prisa, antes de su misión?", ["Había matado a un hombre sin querer de un golpe", "Había robado en el palacio", "Se negó a pagar impuestos", "Había insultado al Faraón"], "Golpeó a un egipcio que peleaba con un hombre de su pueblo y lo mató; se arrepintió de inmediato."),
"prophets_072": ("¿Quién advirtió a Musa de que los jefes tramaban matarlo?", ["Un hombre que vino corriendo desde el extremo de la ciudad", "Su madre", "Harun", "Un soldado"], "«Un hombre vino corriendo del extremo de la ciudad: conspiran para matarte, ¡vete!»"),
"prophets_073": ("Al llegar a Madyan, ¿qué hizo Musa por dos mujeres junto al abrevadero?", ["Abrevó su rebaño", "Les vendió un camello", "Les construyó una casa", "Les enseñó a leer"], "Abrevó su rebaño y luego se retiró a la sombra invocando a Allah."),
"prophets_074": ("¿Cuántos años pidió el anciano de Madyan a Musa que trabajara para casarse con su hija?", ["Ocho, y diez si quería", "Uno", "Cuarenta", "Tres"], "«Me servirás ocho años; si completas diez, será por tu propia voluntad.»"),
"prophets_075": ("¿Qué ordenó Allah a Musa quitarse en el valle sagrado de Tuwa?", ["Sus sandalias", "Su manto", "Su bastón", "Su turbante"], "«Quítate las sandalias: estás en el valle sagrado de Tuwa.»"),
"prophets_076": ("¿Cuál fue la segunda señal dada a Musa, después del bastón?", ["Su mano salió blanca, sin daño", "Podía volar", "Su voz se volvió trueno", "Veía de noche"], "«Lleva tu mano a tu costado: saldrá blanca, sin enfermedad.»"),
"prophets_077": ("¿Qué pidió Musa a Allah antes de ir ante el Faraón?", ["Que ensanchara su pecho y soltara su lengua", "Un ejército", "Oro", "Un caballo veloz"], "«Señor mío, ensancha mi pecho, facilita mi tarea y desata el nudo de mi lengua.»"),
"prophets_078": ("¿A quién pidió Musa a Allah como ayudante en su misión?", ["A su hermano Harun", "A su hijo", "A su suegro", "A un ángel"], "«Dame un ayudante de mi familia: Harun, mi hermano.»"),
"prophets_079": ("¿Qué hicieron los magos del Faraón cuando el bastón de Musa devoró sus ilusiones?", ["Cayeron postrados y creyeron", "Huyeron", "Se rieron", "Atacaron a Musa"], "Los magos cayeron postrados: «Creemos en el Señor de los mundos, el Señor de Musa y Harun»."),
"prophets_080": ("¿Cuál de estas plagas enumera el Corán entre las enviadas contra el pueblo del Faraón?", ["Langostas", "Nieve", "Lobos", "Fuego"], "«Enviamos contra ellos la inundación, las langostas, los piojos, las ranas y la sangre.»"),
"prophets_081": ("Según el Corán, ¿qué hizo Allah con el cuerpo del Faraón tras ahogarse?", ["Lo preservó como señal", "Lo hizo desaparecer", "Lo quemó", "Lo devolvió a su pueblo"], "«Hoy salvaremos tu cuerpo, para que seas una señal para los que vengan después de ti.»"),
"prophets_082": ("Según el Corán, ¿qué pidió a Allah la esposa creyente del Faraón?", ["Una casa junto a Él en el Paraíso", "Un hijo", "La muerte del Faraón", "Un reino"], "«Señor mío, constrúyeme junto a Ti una casa en el Paraíso, y sálvame del Faraón.»"),
"prophets_083": ("¿Cuántas noches duró la cita de Allah con Musa en el monte?", ["Cuarenta", "Siete", "Diez", "Cien"], "«Fijamos a Musa treinta noches y las completamos con diez: cuarenta noches.»"),
"prophets_084": ("¿Qué ocurrió cuando Musa pidió ver a Allah?", ["Allah se manifestó al monte, que se desmoronó, y Musa cayó desmayado", "Vio a Allah", "No pasó nada", "El monte se elevó al cielo"], "«Mira el monte: si permanece en su lugar, Me verás.» El monte fue pulverizado y Musa cayó desmayado."),
"prophets_085": ("¿Sobre qué escribió Allah exhortaciones y explicaciones para Musa?", ["Sobre Tablas", "Sobre hojas de palmera", "Sobre una piedra negra", "Sobre cuero"], "«Le escribimos en las Tablas una exhortación sobre todas las cosas.»"),
"prophets_086": ("¿Quién hizo el becerro que adoraron los Hijos de Israel mientras Musa estaba ausente?", ["As-Samiri", "Harun", "El Faraón", "Qarun"], "«As-Samiri los ha extraviado»: de sus adornos produjo un becerro que mugía."),
"prophets_087": ("¿Cuántos manantiales brotaron de la roca que Musa golpeó con su bastón?", ["Doce", "Siete", "Tres", "Cuarenta"], "«Golpea la roca con tu bastón»: brotaron doce manantiales, uno por cada tribu."),
"prophets_088": ("¿Qué alimento hizo descender Allah a los Hijos de Israel en el desierto?", ["Maná y codornices", "Arroz y pescado", "Dátiles y leche", "Pan y aceitunas"], "«Hicimos descender sobre vosotros el maná y las codornices.»"),
"prophets_089": ("¿De qué color era la vaca que Musa ordenó sacrificar a los Hijos de Israel?", ["Amarillo intenso", "Negra", "Blanca", "Roja"], "«Es una vaca amarilla, de color intenso, que alegra a quienes la miran.»"),
"prophets_090": ("¿Quién, del pueblo de Musa, fue tragado por la tierra con su casa por su arrogancia y riqueza?", ["Qarun", "Haman", "As-Samiri", "Yalut"], "Qarun poseía inmensos tesoros; «hicimos que la tierra se lo tragara a él y a su casa»."),
"prophets_091": ("¿Qué metal ablandó Allah para Dawud?", ["El hierro", "El oro", "El cobre", "La plata"], "«Y le ablandamos el hierro.»"),
"prophets_092": ("¿Qué enseñó Allah a Dawud a fabricar para proteger a la gente en la batalla?", ["Cotas de malla", "Espadas", "Escudos de madera", "Torres"], "«Le enseñamos a fabricar cotas de malla para protegeros.»"),
"prophets_093": ("¿A qué gigante mató Dawud en la batalla, según el Corán?", ["Yalut (Goliat)", "El Faraón", "Haman", "Nimrod"], "«Y Dawud mató a Yalut, y Allah le dio el reino y la sabiduría.»"),
"prophets_094": ("¿Cómo puso a prueba el rey Talut a su ejército antes de enfrentarse a Yalut?", ["Con un río: no beber de él, salvo un sorbo con la mano", "Con una carrera", "Con un ayuno de tres días", "Con una montaña que escalar"], "«Allah os probará con un río: quien beba de él no es de los míos, salvo quien tome un sorbo con la mano.»"),
"prophets_095": ("¿Qué hizo Allah glorificarlo junto con Dawud?", ["Las montañas y los pájaros", "Los vientos", "Los genios", "Los peces"], "«Sometimos las montañas para que Nos glorificaran junto con Dawud, y también los pájaros.»"),
"prophets_096": ("¿Qué elemento sometió Allah a Sulayman para llevarlo adonde quisiera?", ["El viento", "El fuego", "La lluvia", "El mar"], "«Y a Sulayman, el viento, que soplaba con fuerza por orden suya hacia la tierra bendita.»"),
"prophets_097": ("¿Qué ave trajo a Sulayman noticias del reino de Saba?", ["La abubilla", "El águila", "La paloma", "El cuervo"], "La abubilla volvió y dijo: «He sabido algo que tú no sabes, y te traigo de Saba una noticia cierta»."),
"prophets_098": ("¿Qué pequeña criatura avisó a las suyas de entrar en sus casas al acercarse el ejército de Sulayman?", ["Una hormiga", "Una abeja", "Un ratón", "Una araña"], "Una hormiga dijo: «¡Hormigas, entrad en vuestras casas, no os aplasten Sulayman y sus tropas sin darse cuenta!»"),
"prophets_099": ("¿Con qué rapidez fue llevado a Sulayman el trono de la reina de Saba?", ["Antes de que su mirada volviera a él", "En un día", "En siete días", "En un mes"], "El que tenía conocimiento del Libro dijo: «Te lo traeré antes de que tu mirada vuelva a ti»."),
"prophets_100": ("Según el Corán, ¿qué fabricaban los genios para Sulayman?", ["Santuarios, estatuas y grandes recipientes", "Alfombras voladoras", "Barcos", "Montañas"], "«Le hacían lo que quería: santuarios, estatuas, recipientes como aljibes y calderos fijos.»"),
"prophets_101": ("¿Cómo supieron los genios de la muerte de Sulayman?", ["Una criatura de la tierra royó su bastón y él cayó", "Un ángel se lo dijo", "La abubilla se lo dijo", "Lo vieron morir"], "Solo «la criatura de la tierra» que comía su bastón reveló su muerte; los genios comprendieron que no conocían lo oculto."),
"prophets_102": ("¿Qué oración particular hizo Sulayman a Allah?", ["Un reino que nadie después de él tuviera", "Una larga vida", "La riqueza de Qarun", "El poder de volar"], "«Señor mío, perdóname y concédeme un reino que nadie después de mí posea.»"),
"prophets_103": ("¿Qué ordenó Allah a Ayyub para recobrar la salud?", ["Golpear el suelo con el pie: brotó un manantial fresco", "Ayunar un mes", "Bañarse en el mar", "Subir a una montaña"], "«Golpea con tu pie: aquí tienes un manantial fresco para lavarte y beber.»"),
"prophets_104": ("¿Qué súplica hizo Yunus en la oscuridad del vientre del pez?", ["«¡No hay dios sino Tú! Gloria a Ti, he sido de los injustos»", "«Señor mío, dame un reino»", "«Señor mío, envíame lluvia»", "«Señor mío, déjame verte»"], "«Clamó en las tinieblas: no hay dios sino Tú. Gloria a Ti; he sido de los injustos.»"),
"prophets_105": ("¿Qué planta hizo crecer Allah sobre Yunus cuando el pez lo arrojó?", ["Una calabacera (yaqtin)", "Una palmera", "Un olivo", "Una vid"], "«E hicimos crecer sobre él una planta de calabaza.»"),
"prophets_106": ("¿A cuántas personas fue enviado Yunus, según el Corán?", ["A cien mil, o más", "A mil", "A diez mil", "A doce"], "«Y lo enviamos a cien mil, o más.»"),
"prophets_107": ("¿Qué señal dio Allah a Zakariyya para confirmar la llegada de su hijo?", ["No hablar a la gente durante tres noches, estando sano", "Una estrella fugaz", "Lluvia en verano", "Un sueño"], "«Tu señal será que no hablarás a la gente durante tres noches, estando sano.»"),
"prophets_108": ("¿Qué dice Allah sobre el nombre Yahya?", ["Nadie antes que él había recibido ese nombre", "Era el nombre de su abuelo", "Lo eligió su madre", "Era nombre de rey"], "«Te anunciamos un niño cuyo nombre será Yahya; no hemos dado ese nombre a nadie antes.»"),
"prophets_109": ("¿Qué concedió Allah a Yahya siendo aún niño?", ["La sabiduría", "Un reino", "Un caballo", "Un tesoro"], "«Oh Yahya, toma la Escritura con firmeza.» Y le dimos el juicio siendo aún niño."),
"prophets_110": ("¿Qué había prometido la madre de Maryam para el hijo que llevaba?", ["Consagrarlo al servicio de Allah", "Enviarlo a Egipto", "Hacerlo rey", "Confiarlo a un pastor"], "«Señor mío, Te he ofrecido lo que hay en mi vientre, consagrado a Tu servicio.»"),
"prophets_111": ("¿Qué profeta se hizo cargo de Maryam tras su nacimiento?", ["Zakariyya", "Yahya", "Isa", "Dawud"], "«Y la puso al cuidado de Zakariyya», que encontraba junto a ella provisión de Allah."),
"prophets_112": ("Según el Corán, ¿por encima de quiénes eligió Allah a Maryam?", ["De las mujeres de los mundos", "De las reinas", "De los ángeles", "De los profetas"], "«Oh Maryam, Allah te ha elegido y purificado, y te ha elegido por encima de las mujeres de los mundos.»"),
"prophets_113": ("¿Qué cayó para Maryam cuando sacudió el tronco de la palmera?", ["Dátiles frescos y maduros", "Aceitunas", "Higos", "Lluvia"], "«Sacude hacia ti el tronco de la palmera: hará caer sobre ti dátiles frescos y maduros.»"),
"prophets_114": ("¿Qué palabra usa el Corán para Maryam en la sura Al-Ma'ida?", ["Veraz (siddiqa)", "Reina", "Profetisa", "Guerrera"], "«El Mesías, hijo de Maryam, no era sino un mensajero… y su madre era una mujer veraz.»"),
"prophets_115": ("¿Qué título da el Corán a Isa, hijo de Maryam?", ["Al-Masih (el Mesías)", "Al-Jalil", "Al-Kalim", "As-Siddiq"], "«Su nombre será el Mesías, Isa hijo de Maryam, distinguido en este mundo y en el otro.»"),
"prophets_116": ("¿Qué modeló Isa con arcilla, con el permiso de Allah?", ["La forma de un pájaro, que cobró vida", "Una casa", "La estatua de un rey", "Un barco"], "«Modelo para vosotros con arcilla la forma de un pájaro, soplo en él y se convierte en pájaro con el permiso de Allah.»"),
"prophets_117": ("¿Cómo se llaman los compañeros cercanos de Isa, que se declararon «ayudantes de Allah»?", ["Los Hawariyyun (discípulos)", "Los Ansar", "Los Muhayirun", "Los Sahaba"], "«Los discípulos dijeron: somos los ayudantes de Allah.»"),
"prophets_118": ("¿Qué pidieron los discípulos a Isa, dando nombre a la sura Al-Ma'ida?", ["Una mesa servida bajada del cielo", "Un libro", "Un reino", "Oro"], "«¿Puede tu Señor hacernos descender una mesa servida del cielo?»"),
"prophets_119": ("¿Qué dice el Corán sobre el fin de la misión de Isa en la tierra?", ["No fue muerto ni crucificado: Allah lo elevó hacia Sí", "Murió de viejo", "Se ahogó", "Se fue a Egipto"], "«No lo mataron ni lo crucificaron… sino que Allah lo elevó hacia Sí.»"),
"prophets_120": ("¿Con qué nombre anunció Isa a un mensajero que vendría después de él?", ["Ahmad", "Yahya", "Musa", "Ilyas"], "«…anunciando un mensajero que vendrá después de mí, cuyo nombre es Ahmad.»"),
"prophets_121": ("¿Qué ídolo reprochó el profeta Ilyas a su pueblo adorar?", ["Ba'l", "Hubal", "Al-Lat", "Wadd"], "«¿Invocáis a Ba'l y abandonáis al mejor de los creadores?»"),
"prophets_122": ("¿A qué tres profetas menciona juntos el Corán «entre los pacientes»?", ["Isma'il, Idris y Dhul-Kifl", "Nuh, Hud y Salih", "Musa, Harun y Yusha'", "Dawud, Sulayman y Ayyub"], "«E Isma'il, Idris y Dhul-Kifl: todos fueron de los pacientes.»"),
"prophets_123": ("¿Qué profeta es nombrado en la sura Sad junto a Isma'il y Dhul-Kifl?", ["Al-Yasa' (Eliseo)", "Yunus", "Lut", "Shu'ayb"], "«Y recuerda a Isma'il, Al-Yasa' y Dhul-Kifl: todos son de los mejores.»"),
"prophets_124": ("¿Qué título da el Corán al Profeta Muhammad ﷺ en el versículo 33:40?", ["El Sello de los Profetas", "El Rey de los árabes", "El Padre de los creyentes", "El Amigo de Allah"], "«Muhammad… es el Mensajero de Allah y el Sello de los Profetas.»"),
"prophets_125": ("Según el Corán, ¿como qué fue enviado el Profeta Muhammad ﷺ?", ["Como misericordia para los mundos", "Como rey", "Como juez", "Como guerrero"], "«No te hemos enviado sino como misericordia para los mundos.»"),
"prophets_126": ("Según el versículo 33:56, ¿qué hacen Allah y Sus ángeles por el Profeta ﷺ?", ["Le envían bendiciones", "Lo protegen del viento", "Le envían lluvia", "Lo observan en silencio"], "«Allah y Sus ángeles bendicen al Profeta. ¡Creyentes, bendecidlo y saludadlo con la paz!»"),
"prophets_127": ("¿Cómo describe el Corán el carácter del Profeta ﷺ en la sura Al-Qalam?", ["«Eres de un carácter inmenso»", "«Eres un gran rey»", "«Eres el más rico»", "«Eres el más fuerte»"], "«Y ciertamente eres de un carácter inmenso.»"),
"prophets_128": ("¿Qué recuerda el versículo 3:144 sobre Muhammad ﷺ?", ["No es sino un mensajero, y antes de él pasaron otros mensajeros", "Nunca morirá", "Es un ángel", "Conoce el futuro"], "«Muhammad no es sino un mensajero; antes de él pasaron otros mensajeros.»"),
"prophets_129": ("¿Qué cinco profetas nombra juntos el versículo 33:7 para el pacto solemne?", ["Nuh, Ibrahim, Musa, Isa y Muhammad ﷺ", "Adam, Nuh, Hud, Salih y Lut", "Dawud, Sulayman, Ayyub, Yunus e Idris", "Isma'il, Ishaq, Ya'qub, Yusuf y Musa"], "«Tomamos de los profetas su pacto: de ti, de Nuh, Ibrahim, Musa e Isa hijo de Maryam.»"),
"prophets_130": ("Según un hadiz de al-Bujari, ¿qué oficio ejerció todo profeta?", ["Pastor", "Carpintero", "Herrero", "Mercader"], "«Allah no envió ningún profeta que no hubiera pastoreado ovejas», y el Profeta ﷺ las pastoreó para la gente de La Meca."),
"prophets_131": ("Según un hadiz de Muslim, ¿qué profeta trabajó como carpintero?", ["Zakariyya", "Nuh", "Idris", "Yusuf"], "El Profeta ﷺ dijo: «Zakariyya era carpintero»."),
"prophets_132": ("¿De qué profeta dijo el Profeta ﷺ que era «el más cercano de la gente» a él, en este mundo y en el otro?", ["Isa hijo de Maryam", "Musa", "Ibrahim", "Nuh"], "«Soy el más cercano de toda la gente a Isa hijo de Maryam en este mundo y en el otro; los profetas son hermanos.»"),
"prophets_133": ("¿Cuántas suras del Corán llevan el nombre de un profeta?", ["Seis", "Dos", "Doce", "Veinticinco"], "Yunus (10), Hud (11), Yusuf (12), Ibrahim (14), Muhammad (47) y Nuh (71)."),
"prophets_134": ("¿Con qué tres palabras describe el Corán a Ibrahim en el versículo 11:75?", ["Indulgente, tierno de corazón, siempre vuelto a Allah", "Rico, poderoso, sabio", "Fuerte, rápido, valiente", "Rey, juez, guerrero"], "«Ciertamente, Ibrahim era indulgente, compasivo y siempre vuelto a Allah.»"),
"prophets_135": ("¿Qué reprochó Shu'ayb a su pueblo, además de la idolatría?", ["Engañar en los pesos y medidas", "No rezar", "Viajar de noche", "Comer pescado"], "«Dad la medida y el peso completos, y no privéis a la gente de lo suyo.»"),
"prophets_136": ("¿Qué alcanzó al pueblo de Shu'ayb tras rechazar su mensaje?", ["Un terremoto", "Un diluvio", "Una lluvia de fuego", "Una bandada de pájaros"], "«El terremoto los alcanzó, y amanecieron en sus casas caídos de bruces.»"),
"prophets_137": ("¿Qué noticia dieron los ángeles a Ibrahim tras calmar su temor?", ["Que habían sido enviados al pueblo de Lut", "Que venía un diluvio", "Que la Ka'ba sería destruida", "Que el Faraón se ahogaría"], "«No temas: hemos sido enviados al pueblo de Lut.»"),
"prophets_138": ("¿Qué pidió Ibrahim para sí y sus descendientes en el versículo 14:40?", ["Ser de los que cumplen la oración", "Ser reyes", "Ser ricos", "Vivir mucho"], "«Señor mío, haz que yo cumpla la oración, y también mi descendencia.»"),
"prophets_139": ("Al final de la historia de Yusuf, ¿a quién hizo subir al trono antes de que todos se postraran ante él?", ["A sus padres", "Al rey", "A sus hermanos", "A su hijo"], "«Hizo subir a sus padres al trono, y cayeron postrados ante él»: el sueño de la infancia se cumplió."),
"prophets_140": ("¿Por qué querían los hermanos de Yusuf deshacerse de él?", ["Por celos: su padre lo amaba más", "Había robado", "Se negaba a trabajar", "Estaba enfermo"], "«Yusuf y su hermano son más queridos para nuestro padre que nosotros… Matad a Yusuf o desterradlo a alguna tierra.»"),
"prophets_141": ("¿Qué trajeron los hermanos de Yusuf a su padre para hacerle creer que un lobo lo había devorado?", ["Su camisa manchada de sangre falsa", "Sus sandalias", "Su bastón", "El diente de un lobo"], "«Trajeron su camisa con sangre falsa»; Ya'qub respondió: «Paciencia, es lo más hermoso»."),
"prophets_142": ("¿Qué prometió Allah a la madre de Musa al inspirarle ponerlo en el río?", ["Devolvérselo y hacerlo mensajero", "Darle otro hijo", "Hacerla reina", "Enviar lluvia"], "«No temas ni te aflijas: te lo devolveremos y lo haremos uno de los mensajeros.»"),
"prophets_143": ("¿Con qué golpeó Musa el mar para que se abriera?", ["Con su bastón", "Con su mano", "Con una piedra", "Con su espada"], "«Golpea el mar con tu bastón»: se abrió, y cada lado era como una gran montaña."),
"prophets_144": ("¿Qué fue lo primero que dijo Allah a Musa al dirigirse a él?", ["«Yo soy Allah, no hay dios sino Yo: adórame y cumple la oración»", "«Ve a pescar»", "«Construye un arca»", "«Vuelve ante el Faraón»"], "«Ciertamente, Yo soy Allah; no hay dios sino Yo, adórame y cumple la oración para recordarme.»"),
"prophets_145": ("¿Cómo dijo Allah a Musa y Harun que hablaran al Faraón?", ["Con palabras suaves", "Con ira", "Gritando", "En silencio"], "«Id al Faraón… y habladle con palabras suaves; quizá reflexione o tema.»"),
"prophets_146": ("¿Qué dijo Musa a su joven sirviente al comenzar su viaje a la confluencia de los dos mares?", ["Que no se detendría hasta llegar a la confluencia de los dos mares", "Que quería volver a casa", "Que tenía miedo", "Que buscaba oro"], "«No cesaré hasta llegar a la confluencia de los dos mares, aunque camine durante mucho tiempo.»"),
"prophets_147": ("¿Cuál de estas cosas hizo el siervo sabio ante Musa, que no lo comprendió en el momento?", ["Agujereó una barca", "Construyó un puente", "Encendió un fuego", "Plantó un árbol"], "Agujereó la barca, luego mató a un muchacho y enderezó un muro; después explicó a Musa cada acto."),
"prophets_148": ("¿Cuáles fueron las primeras palabras de Isa, aún en la cuna?", ["«Soy el siervo de Allah; me ha dado la Escritura y me ha hecho profeta»", "«Soy el hijo de Dios»", "«Soy un rey»", "«Tengo hambre»"], "«Dijo: soy el siervo de Allah. Me ha dado la Escritura y me ha hecho profeta.»"),
"prophets_149": ("¿Qué dijeron Adam y su esposa a Allah tras comer del árbol?", ["«Señor nuestro, hemos sido injustos con nosotros mismos; si no nos perdonas, estaremos perdidos»", "«No fue culpa nuestra»", "«Fue culpa del árbol»", "No dijeron nada"], "«Señor nuestro, hemos sido injustos con nosotros mismos, y si no nos perdonas y te apiadas de nosotros, seremos de los perdedores.»"),
"prophets_150": ("¿Qué misión dio Allah a Nuh hacia su pueblo, en el primer versículo de la sura Nuh?", ["Advertirles antes de que les llegara un castigo doloroso", "Construir una ciudad", "Enseñarles a pescar", "Hacerlos reyes"], "«Enviamos a Nuh a su pueblo: advierte a tu pueblo antes de que les llegue un castigo doloroso.»"),
}
